const user = $.steps.getCurrentUser.response?.resource || $.steps.getCurrentUser.response || {};
const userUri = user.uri || '';
if (!userUri) throw new Error('Could not determine current user URI');
const params = { user: userUri, count: String($.input.count || 20) };
if ($.input.status) params.status = $.input.status;
if ($.input.minStartTime) params.min_start_time = $.input.minStartTime;
if ($.input.maxStartTime) params.max_start_time = $.input.maxStartTime;
return { params, userUri };

const resp = $.steps.listEvents.response || {};
const events = resp.collection || [];
return {
  events: events.map(e => ({
    uri: e.uri,
    name: e.name,
    status: e.status,
    startTime: e.start_time,
    endTime: e.end_time,
    eventType: e.event_type,
    location: e.location || {},
    inviteesCount: e.invitees_counter?.total || 0
  })),
  count: events.length,
  pagination: resp.pagination || {},
  summary: `Found ${events.length} scheduled event${events.length === 1 ? '' : 's'}`
};
